import math

def check_condition(n):
    """
    Checks if k^2 == 1 (mod n) for all k coprime to n.
    """
    if n <= 1:
        return False, "n must be >= 2"

    coprime_k = []
    for k in range(1, n):
        if math.gcd(k, n) == 1:
            coprime_k.append(k)

    if not coprime_k:
        # This should only happen for n=1, which is filtered above
        return True, "No coprime elements (vacuously true)"

    # Test the condition for every coprime k
    for k in coprime_k:
        if (k * k) % n != 1:
            # Found a counterexample
            return False, f"Counterexample found: k={k}, k^2 = {k*k}. {k*k} mod {n} is {(k*k) % n}, not 1."

    # If the loop completes, the condition holds
    return True, "Condition satisfied."

candidates = [2, 3, 4, 6, 8, 12, 24]
results = {}

for n in candidates:
    is_solution, message = check_condition(n)
    results[n] = (is_solution, message)

# Print results in a readable format
for n, (is_sol, msg) in results.items():
    print(f"n={n}: Solution? {is_sol} - Message: {msg}")
